fn comp(cv:&[u32;8],bw:&[u32;16],c:u64,bl:u32,f:u32,p:&[usize;16])->[u32;16]{let mut s=[0u32;16];s[0..8].copy_from_slice(cv);s[8..12].copy_from_slice(&IV[0..4]);s[12]=c as u32;s[13]=(c>>32) as u32;s[14]=bl;s[15]=f;let mut m=*bw;for _ in 0..7{rnd(&mut s,&m);m=pm(&m,p);}for i in 0..8{s[i]^=s[i+8];s[i+8]^=cv[i];}s}
