fn main(){let e="ea8f163db38682925e4491c5e58d4bb3506ef8c14eb78a86e908c5624a67200f";let g0=[B[0],B[1],B[2],B[3]];let g1=[B[4],B[5],B[6],B[7]];let g2=[B[8],B[9],B[10],B[11]];let g3=[B[12],B[13],B[14],B[15]];let gs=[g0,g1,g2,g3];for a in 0..4{for b in 0..4{if b==a{continue}for c in 0..4{if c==a||c==b{continue}for d in 0..4{if d==a||d==b||d==c{continue}let mut p=[0usize;16];for i in 0..4{p[i]=gs[a][i];p[4+i]=gs[b][i];p[8+i]=gs[c][i];p[12+i]=gs[d][i];}if hh(&p)==e{println!("MATCH groups {} {} {} {} {:?}",a,b,c,d,p);return;}}}}}println!("no group perm match");}
